import{_ as r,o as d,c as n,a5 as i,j as o,a as t,t as a}from"./chunks/framework.BfQ7H7Qx.js";const f=JSON.parse('{"title":"Smart Reference Hub, Shared Moodboard & Client-Side Algorithmic Curation Engine","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/reference-hub-and-algorithmic-curation/spec.md","filePath":"feature/modules/04-task-chat-vault/reference-hub-and-algorithmic-curation/spec.md"}'),c={name:"feature/modules/04-task-chat-vault/reference-hub-and-algorithmic-curation/spec.md"};function s(l,e,u,g,p,m){return d(),n("div",null,[e[22]||(e[22]=i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="smart-reference-hub-shared-moodboard-client-side-algorithmic-curation-engine" tabindex="-1">Smart Reference Hub, Shared Moodboard &amp; Client-Side Algorithmic Curation Engine <a class="header-anchor" href="#smart-reference-hub-shared-moodboard-client-side-algorithmic-curation-engine" aria-label="Permalink to &quot;Smart Reference Hub, Shared Moodboard &amp; Client-Side Algorithmic Curation Engine&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>reference-hub-and-algorithmic-curation</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>04-task-chat-vault</code> — Task Workflow, Realtime Workspace Chat &amp; Encrypted S3 Vault</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>smart-reference-hub</code>, <code>workspace-shared-moodboard</code>, <code>reference-preview-textrank</code>, <code>specialized-task-reference-rail</code>, <code>scene-broll-visual-pills</code>, <code>cross-modal-content-kit-pairing</code>, <code>dynamic-keyphrase-facet-clustering</code>, <code>cielab-color-harmony-matcher</code>, <code>duration-storyboard-broll-assigner</code>, <code>session-rocchio-mmr-reranker</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.1–3.6.15</code>) · <a href="./../../../srs/06-ai-features/README.html">3.7 AI Features</a> (<code>3.7.1</code>, <code>3.7.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver an end-to-end, <strong>0-Credit Content Research, Moodboard Curation &amp; Deterministic Algorithmic Recommendation Layer</strong> across BrandHub&#39;s Post Editor, Specialized Task Section Editors (<code>KOL</code>, <code>PRESS</code>, <code>EVENT</code>, <code>WORKSHOP</code>, <code>NEWSLETTER</code>, <code>SURVEY</code>), Video Script Storyboards, and Workspace Content Library — <strong>strictly decoupled from core LLM/generative AI endpoints</strong> so high-volume multi-provider API streams (<code>Pexels</code>, <code>Unsplash</code>, <code>Pixabay</code>, <code>Openverse</code>, <code>Wikimedia</code>, <code>VN_PRESS</code>, <code>GDELT</code>, <code>Wikipedia</code>, and <code>EXTERNAL</code> links) are classified, paired, color-matched, duration-aligned, and personalized in <code>&lt; 5 ms</code> directly on structured API metadata.</p><p>Specifically, this module unifies:</p>',6)),o("ol",null,[e[13]||(e[13]=i("<li><strong>Multi-Source Reference Hub &amp; Shared Moodboard (<code>WorkspaceReferenceController</code>):</strong> Workspace/Campaign/Task-scoped discovery, URL unfurling with <strong>TextRank Key Takeaways</strong> (<code>extract_key_takeaways</code>), collaborative pinning, and <code>Owner</code> / <code>Manager</code> / <code>Client</code> <code>APPROVED</code> curation notes surfaced directly inside authoring tools.</li><li><strong>In-App Rich Reference Preview (<code>ReferencePreviewModal</code>) &amp; Specialized Task Rail (<code>SimpleSectionEditorPage</code>):</strong> Full reader/video/HD-photo preview modal with 1-click Brief/Section insertion across both social posts and all 6 non-post task editors, plus clean visual B-roll attachment pills on video script rows.</li>",2)),o("li",null,[e[12]||(e[12]=o("strong",null,"Five Deterministic Client/Core Curation Algorithms (Zero LLM Cost, AI-Team Decoupled):",-1)),o("ul",null,[e[11]||(e[11]=i("<li><strong>Algo 1 — Cross-Modal &quot;Content Kit&quot; Tripartite Pairing:</strong> Pairs <code>[1 Editorial Article + 1 Still Visual + 1 Video B-roll]</code> via bilingual <strong>BM25+ Cosine</strong> + Weighted Tag Jaccard + Platform Aspect Bonus + <strong>CIEDE2000 ($\\Delta E_{00}$) Cross-Visual Harmony</strong> into 1-click <strong>&quot;Ready-to-Use Content Kits&quot;</strong> (supported atomically in both <code>EditorPage</code> and <code>SimpleSectionEditorPage</code>).</li><li><strong>Algo 2 — Dynamic Keyphrase &amp; Agglomerative Jaccard Facet Clustering:</strong> Automatically groups large heterogeneous API result pools (in both <code>EditorInspirationPanel</code> and <code>WorkspaceMoodboardPanel</code> Discover mode) into 4–5 acronym-preserving sub-topic facets with live counts and a horizontal <strong>Swimlanes (&quot;Kệ chủ đề&quot;)</strong> view.</li><li><strong>Algo 3 — Perceptual CIELAB ($\\Delta E_{00}$ CIEDE2000) Color-Harmony &amp; Carousel Cohesion Matcher:</strong> Converts <code>dominantColor</code> HEX values into perceptual CIE $L^*a^<em>b^</em>$ space (<code>sRGB -&gt; D65 XYZ -&gt; Lab</code>) and applies <strong>ISO/CIE CIEDE2000 ($\\Delta E_{00}$)</strong> to classify visual mood buckets and score multi-image <strong>Carousel Cohesion</strong> against selected post media and <code>APPROVED</code> Moodboard pins.</li><li><strong>Algo 4 — Global Beam-Viterbi Duration-Constrained Storyboard Sequence Assignment:</strong> Parses per-scene target durations $\\Delta t_k$ (<code>0-4s</code> $\\rightarrow 4\\text{s}$) in <code>VIDEO.SCRIPT</code> / <code>SHORT_VIDEO.SCRIPT</code> and runs <strong>Beam-Viterbi Dynamic Programming ($B = 12$)</strong> across the scene lattice to maximize global lexical fit, duration coverage ($\\text{dur}<em>v \\ge \\Delta t_k$), and adjacent visual continuity ($\\Delta E</em>{00}$ + aspect alignment) without greedy local traps.</li>",4)),o("li",null,[e[0]||(e[0]=o("strong",null,'Algo 5 — Temporal-Decay Session Rocchio + MMR Re-Ranking & Explainable "More Like This":',-1)),e[1]||(e[1]=t(" Combines ",-1)),e[2]||(e[2]=o("code",null,"APPROVED",-1)),t(" Moodboard priors, recency-weighted positive session actions ($0.92^{\\text{age"+a("}}")+"$), and negative dismissals (",1),e[3]||(e[3]=o("code",null,"× Ẩn mẫu",-1)),e[4]||(e[4]=t(") via a ",-1)),e[5]||(e[5]=o("strong",null,"Rocchio Relevance Feedback",-1)),e[6]||(e[6]=t(" preference vector + ",-1)),e[7]||(e[7]=o("strong",null,"Maximal Marginal Relevance ($\\lambda = 0.78$)",-1)),e[8]||(e[8]=t(" diversity re-ranking with explainable boost tooltips and instant k-NN ",-1)),e[9]||(e[9]=o("strong",null,'"Tìm tương tự"',-1)),e[10]||(e[10]=t(" exploration.",-1))])])])]),e[23]||(e[23]=i('<h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Creator</code>, when API providers return dozens of mixed articles, photos, and B-roll clips, I want the UI to automatically cluster them into clear sub-topics, pair them into ready-to-use <code>[Article + Photo + Video]</code> Content Kits, and adapt rankings to my session clicks and <code>APPROVED</code> Moodboard guidelines so I can assemble a post or press draft in 1 click without manually sifting through flat cards.</li><li>As a <code>Creator</code> writing a multi-scene Video Script (<code>VIDEO.SCRIPT</code> or <code>SHORT_VIDEO.SCRIPT</code>), I want a 1-click <strong>&quot;Auto-Match B-roll for Full Script&quot;</strong> workflow that assigns non-duplicate clips matching each scene&#39;s exact duration (<code>durationSeconds</code>) and camera description into clean visual B-roll pills.</li><li>As a <code>Creator</code> building a multi-photo Facebook/Instagram carousel, I want perceptual CIELAB color-mood filters and a <strong>Carousel Cohesion Badge</strong> indicating which candidate visuals harmonize with the photos already attached to my post.</li><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Client</code>, I want to pin external/discovered references onto the Campaign Moodboard, mark approved references as <code>APPROVED</code> with creative direction notes (<code>note</code>), and know that <code>Creator</code> immediately sees those <code>APPROVED</code> pins at the top of the Editor Reference Hub and inside specialized Task Editors.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2>',3)),o("ol",null,[e[20]||(e[20]=i("<li><strong>Workspace Reference Hub, Shared Moodboard &amp; Role Governance:</strong><ul><li><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, and <code>Client</code> members of a Workspace can query <code>POST /api/v1/workspaces/{workspaceId}/references/recommend</code>, unfurl URLs via <code>POST /unfurl</code>, and list/pin items on <code>GET/POST /moodboard</code>.</li><li>Only <code>Owner</code>, <code>Manager</code>, and <code>Client</code> can transition <code>approvalStatus</code> (<code>PENDING &lt;-&gt; APPROVED</code>) on Moodboard pins; <code>Creator</code> sees <code>APPROVED</code> pins (with <code>approvedByName</code> and <code>note</code>) surfaced directly in a dedicated <strong>&quot;Đã chốt trên Moodboard&quot;</strong> strip inside <code>EditorInspirationPanel</code> and as positive priors in session re-ranking.</li></ul></li><li><strong>In-App Preview Modal, Specialized Task Rail &amp; Visual B-roll Pills:</strong><ul><li>Clicking any reference card in <code>EditorInspirationPanel</code>, <code>WorkspaceMoodboardPanel</code>, <code>EditorTaskContextPanel</code>, <code>SceneBrollPopover</code>, or <code>SectionListField</code> opens <code>ReferencePreviewModal</code> displaying full video/image media or extracted article paragraphs + TextRank <code>keyTakeaways</code> with 1-click Brief/Section insertion.</li><li><code>SimpleSectionEditorPage</code> (<code>kol-editor</code>, <code>press-editor</code>, <code>event-editor</code>, <code>workshop-editor</code>, <code>newsletter-editor</code>, <code>survey-editor</code>) provides a 3-tab right rail (<code>Xem trước</code> | <code>Tham khảo</code> | <code>Yêu cầu</code>).</li><li>Attaching B-roll to <code>VIDEO.SCRIPT</code> or <code>SHORT_VIDEO.SCRIPT</code> stores structured <code>row.brolls</code> (and auto-migrates legacy <code>[B-roll mẫu: ...]</code> text tags) rendered as interactive thumbnail/duration pills without polluting dialogue text.</li></ul></li><li><strong>Algo 1 — Cross-Modal &quot;Content Kit&quot; Tripartite Pairing:</strong><ul><li>When the candidate pool contains at least 2 distinct modalities (<code>ARTICLE</code>/<code>KNOWLEDGE</code>, <code>IMAGE</code>/<code>VECTOR</code>, <code>VIDEO</code>), <code>buildCrossModalContentKits</code> computes cross-modal affinity (TF-IDF Cosine + Tag Jaccard + Platform Aspect Bonus) and renders up to <code>3</code> <strong>Content Kit</strong> cards at the top of <code>EditorInspirationPanel</code> (when <code>mediaFilter === &quot;ALL&quot;</code>).</li><li>Clicking <strong>&quot;Dùng trọn bộ&quot;</strong> (<code>Apply Kit</code>) inserts the kit&#39;s visual asset(s) into Post Media (or section materials) and attaches the paired editorial source into Brief/Research in a single atomic UI action.</li></ul></li><li><strong>Algo 2 — Dynamic Keyphrase &amp; Jaccard Facet Clustering:</strong><ul><li><code>buildDynamicFacetClusters</code> extracts bilingual salient keyphrases from <code>tags</code>, <code>matchReasons</code>, and <code>title</code>, merges overlapping clusters ($J \\ge 0.65$), and selects up to <code>5</code> high-coverage topic chips (<code>label + count</code>) plus a toggleable <strong>Swimlanes (&quot;Kệ chủ đề&quot;)</strong> layout grouping cards into horizontal topic shelves.</li><li>When <code>mediaFilter === &quot;ARTICLE&quot;</code>, AI expanded query chips switch to Vietnamese/localized <code>expandedEditorialQueries</code> instead of English visual stock queries.</li></ul></li><li><strong>Algo 3 — Perceptual CIELAB ($\\Delta E$) Color-Harmony &amp; Carousel Cohesion:</strong><ul><li><code>colorHarmony.ts</code> converts <code>dominantColor</code> HEX strings to CIE $L^*a^<em>b^</em>$ (<code>L</code>, <code>a</code>, <code>b</code>, Chroma <code>C</code>, Hue <code>hDeg</code>) to expose interactive <strong>Color Mood Swatch</strong> filters (<code>Tất cả màu</code>, <code>Hợp màu đang chọn</code>, <code>Ấm năng động</code>, <code>Sáng tối giản</code>, <code>Tối điện ảnh</code>, <code>Mát hiện đại</code>).</li><li>Visual cards display their <code>dominantColor</code> swatch dot; whenever reference palette anchors exist (from inserted post media colors or <code>APPROVED</code> Moodboard pins), visual cards with high perceptual harmony display a <strong><code>Hợp bộ màu · XX%</code></strong> cohesion badge.</li></ul></li><li><strong>Algo 4 — Duration-Constrained Storyboard Sequence Assignment:</strong><ul><li>In <code>SectionListField</code> (<code>name === &quot;scenes&quot;</code> and <code>!disabled</code>), a header button <strong>&quot;Tự ghép B-roll toàn kịch bản&quot;</strong> opens <code>StoryboardAutoAssignModal</code>, parses target seconds $\\Delta t_k$ from each row&#39;s <code>time</code> cell, fetches a unified visual pool, and runs <code>assignStoryboardBrolls</code> to assign non-duplicate clips optimizing lexical fit ($0.50$), duration coverage ($0.30$), and adjacent visual continuity ($0.20$).</li><li>Users can cycle alternative clips per scene (<code>Đổi mẫu</code>) and click <strong>&quot;Áp dụng cho kịch bản&quot;</strong> to populate <code>row.brolls</code> across all matched scenes at once.</li></ul></li>",6)),o("li",null,[e[19]||(e[19]=o("strong",null,'Algo 5 — Session Implicit-Feedback Rocchio + MMR Re-Ranking & "More Like This":',-1)),o("ul",null,[o("li",null,[e[14]||(e[14]=t("User interactions within the editor session (inserting media, saving to brief, pinning, previewing, or clicking ",-1)),e[15]||(e[15]=o("code",null,"× Ẩn mẫu",-1)),e[16]||(e[16]=t(") together with ",-1)),e[17]||(e[17]=o("code",null,"APPROVED",-1)),t(" Moodboard pins update the session preference vector $\\vec{w}_{\\text{user"+a("}}")+"$ via Rocchio feedback and re-rank remaining items with MMR ($\\lambda = 0.78$).",1)]),e[18]||(e[18]=o("li",null,[t("Clicking "),o("strong",null,'"Tìm tương tự"'),t(" on a card or inside "),o("code",null,"ReferencePreviewModal"),t(" activates a k-NN similarity filter chip ("),o("code",null,"Tương tự: <Title>"),t(") ranking the candidate pool by multi-feature cosine/Jaccard similarity to that seed item.")],-1))])]),e[21]||(e[21]=i("<li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong><ul><li>Every user-facing label, badge, cluster header, mood filter, storyboard dialog control, and toast message uses key-parallel translations under <code>editor.{inspiration,referencePreview,sceneBroll,sectionRail,contentKit,colorHarmony,storyboardAssign}.*</code> in <code>brandhub-web/src/i18n/locales/{vi,en}/editor.json</code> with 100% key parity (<code>i18nParityAudit.test.ts</code>) and zero hardcoded JSX strings.</li></ul></li><li><strong>Light &amp; Dark Mode + UI Craft &amp; Accessibility (<code>DESIGN.md</code>, <code>baseline-ui</code>, <code>fixing-accessibility</code>):</strong><ul><li>All surfaces, cards, pills, and modals use semantic CSS tokens (<code>bg-card</code>, <code>bg-background</code>, <code>bg-muted</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>) and paired <code>dark:</code> variants, strictly respecting 1px borders (no <code>border-l-3/4/8</code>), zero multicolor gradients, <code>rounded-md</code> chips/badges (no bare <code>rounded</code>), <code>&gt;= 28px</code> touch targets (<code>min-h-7</code> / <code>size-7</code>), structural <code>&lt;Skeleton /&gt;</code> loading cards (<code>role=&quot;status&quot; aria-busy=&quot;true&quot;</code>), <code>aria-expanded</code> / <code>aria-controls</code> / <code>aria-pressed</code> semantics, <code>text-balance</code> / <code>text-pretty</code> typography, and <code>font-mono tabular-nums</code> on counts/durations/percentages (<code>designSystemCraftAudit.test.ts</code>).</li></ul></li>",2))]),e[24]||(e[24]=i('<h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong><ul><li><code>src/pages/editor/components/EditorInspirationPanel.tsx</code> (Approved Moodboard strip, Content Kit carousel, Dynamic Facet Cluster bar + Swimlanes toggle, CIELAB Mood Swatches, Rocchio/More-Like-This controls)</li><li><code>src/pages/editor/index.tsx</code> (wires <code>onApplyContentKit</code>, selected media color anchors, and 1-click AI Caption seed handoff)</li><li><code>src/components/reference-hub/ReferencePreviewModal.tsx</code> (Reader/Video/Image preview, TextRank Key Takeaways, <code>&quot;Tìm tương tự&quot;</code> trigger)</li><li><code>src/components/reference-hub/WorkspaceMoodboardPanel.tsx</code> (Shared Moodboard pinning, <code>APPROVED</code> sign-off, curator notes)</li><li><code>src/pages/tasks/components/SimpleSectionEditorPage.tsx</code> (3-tab right rail for <code>KOL</code>, <code>PRESS</code>, <code>EVENT</code>, <code>WORKSHOP</code>, <code>NEWSLETTER</code>, <code>SURVEY</code>)</li><li><code>src/components/task-sections/{SectionListField,SceneBrollPopover,StoryboardAutoAssignModal}.tsx</code> (Visual B-roll pills, <code>9:16</code>/<code>16:9</code> orientation selector, whole-script Auto-Storyboard dialog)</li><li><code>src/lib/referenceAlgorithms/{textSimilarity,colorHarmony,facetClustering,contentKitPairing,sessionRocchio,storyboardAssigner}.ts</code></li></ul></li><li><strong>UI States:</strong><ul><li><strong>Loading:</strong> Deterministic spinner/skeleton states during initial candidate pool fetch or article unfurl.</li><li><strong>Empty / Narrow Filter:</strong> Clear reset action when a combination of Facet Cluster + CIELAB Color Mood filter yields 0 items, without fabricating mock items.</li><li><strong>Adaptive / Active Feedback:</strong> Dismissed items (<code>×</code>) fade out immediately; <code>&quot;Tương tự: ...&quot;</code> and <code>&quot;Đã chốt Moodboard&quot;</code> chips display active clearable badges.</li><li><strong>Offline / Fallback Resilience:</strong> <code>referenceHubService.recommend</code> falls back gracefully to CORS-safe public providers (<code>Openverse</code>, <code>Wikimedia</code>, <code>Wikipedia</code>) if downstream discovery is temporarily unreachable, and all 5 client-side algorithms operate identically on fallback pools.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Engine Boundary</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service / Module &amp; Responsibility</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/references/recommend</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>WorkspaceReferenceController</code> -&gt; <code>WorkspaceReferenceService</code> -&gt; multi-provider candidate pool (<code>ReferenceRecommendResult</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/references/unfurl</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>WorkspaceReferenceController</code> -&gt; article paragraphs + TextRank <code>keyTakeaways</code> (<code>ReferenceUnfurlResult</code>)</td></tr><tr><td style="text-align:left;"><code>GET/POST/PATCH/DELETE /api/v1/workspaces/{workspaceId}/references/moodboard/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>; <code>APPROVED</code> restricted to <code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>WorkspaceReferenceController</code> -&gt; MongoDB <code>workspace_moodboard_items</code> (<code>MoodboardItemDocument</code>)</td></tr><tr><td style="text-align:left;"><code>src/lib/referenceAlgorithms/*</code></td><td style="text-align:left;">Client-Side Pure TS (<code>0</code> network calls, <code>&lt; 5 ms</code>)</td><td style="text-align:left;">Tripartite Kit Pairing, Facet Clustering, CIELAB $\\Delta E$ Harmony, Storyboard Sequence Assigner, Session Rocchio + MMR</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Cross-Tenant Isolation &amp; Role Enforcement:</strong> <code>WorkspaceReferenceService</code> validates Workspace membership before reading/mutating <code>workspace_moodboard_items</code>; <code>Creator</code> attempts to mutate <code>approvalStatus</code> are blocked both in UI (<code>canApprove</code>) and backend service checks (<code>403 FORBIDDEN</code>).</li><li><strong>Missing Optional Metadata:</strong> Items lacking <code>dominantColor</code> (e.g., <code>ARTICLE</code> or <code>WIKIMEDIA</code> clips) bypass color-bucket exclusion when <code>&quot;ALL&quot;</code> mood is active and receive neutral color weight (<code>0.5</code>) during sequence/kit scoring rather than throwing <code>NaN</code>.</li><li><strong>Small / Single-Modality Pool:</strong> When fewer than 2 modalities exist (e.g., user filters <code>VIDEO</code> only), <code>buildCrossModalContentKits</code> cleanly returns <code>[]</code> and hides the Content Kit shelf without empty placeholders.</li><li><strong>Short / Unstructured Scene Durations:</strong> Scenes with empty or non-numeric <code>time</code> strings default cleanly to $\\Delta t_k = 5\\text{s}$ in <code>parseSceneDurationSeconds</code>; if scenes outnumber unique candidate videos, remaining scenes fall back to best-matching still frames or remain unassigned rather than duplicating clips.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling Module:</strong> <a href="./../task-subtask-and-inline-workflow/spec.html">Five-State Inline Task Editing &amp; Sectioned Specialized Editors</a></li><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> · <a href="./../../../srs/06-ai-features/README.html">3.7 AI Features</a></li><li><strong>Rules &amp; Craft Standards:</strong> <a href="./../../../../rule/feature-workflow.html">Feature Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Complete 4-doc suite (<code>spec.md</code>, <code>plan.md</code>, <code>task.md</code>, <code>test.md</code>) committed in <code>brandhub-infrastructure</code>; all 5 algorithmic engines implemented in <code>src/lib/referenceAlgorithms/</code> and wired into <code>EditorInspirationPanel</code>, <code>EditorPage</code>, <code>ReferencePreviewModal</code>, <code>SimpleSectionEditorPage</code>, and <code>SectionListField</code>; 100% <code>vi</code>/<code>en</code> locale key parity; Light/Dark &amp; Design System Craft audits green; all automated unit &amp; algorithmic tests in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> Modifying LLM prompt pipelines or GPU workers owned by the AI team (<code>brandhub-ai-service</code> generative endpoints), paid stock licensing checkout, or de-scoped SRS features (livestreaming, Zalo OA, VNPay/Stripe, plagiarism scanning).</li></ul>',10))])}const b=r(c,[["render",s]]);export{f as __pageData,b as default};
